const CODE_ALPHABET = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"; // 헷갈리는 0/O, 1/I 제외
const CODE_LEN = 6;
const CODE_RE = /^[A-HJ-NP-Z2-9]{6}$/;
