// ---------------------------------------------------------------- 유틸
const json = (data, status = 200, headers = {}) =>
  new Response(JSON.stringify(data), { status, headers: { "content-type": "application/json; charset=utf-8", ...headers } });

function randomCode() {
  const buf = new Uint8Array(CODE_LEN);
  crypto.getRandomValues(buf);
  let s = "";
  for (const b of buf) s += CODE_ALPHABET[b % CODE_ALPHABET.length];
  return s;
}

function randomId(len = 10) {
  const buf = new Uint8Array(len);
  crypto.getRandomValues(buf);
  return Array.from(buf, (b) => (b % 36).toString(36)).join("");
}

const num = (v, lim = 20000) => {
  const n = Number(v);
  if (!Number.isFinite(n)) return 0;
  return Math.max(-lim, Math.min(lim, Math.round(n * 100) / 100));
};
const vec3 = (a, lim) => (Array.isArray(a) && a.length >= 3 ? [num(a[0], lim), num(a[1], lim), num(a[2], lim)] : null);
const int = (v, lo, hi) => Math.max(lo, Math.min(hi, Math.round(Number(v) || 0)));

/** 닉네임 정리: 제어문자·꺾쇠 제거, 공백 정리, 최대 16자 */
function cleanName(raw) {
  let s = String(raw ?? "")
    .replace(/[\u0000-\u001f\u007f<>]/g, "")
    .replace(/\s+/g, " ")
    .trim();
  s = Array.from(s).slice(0, 16).join("");
  return s;
}

function cleanChat(raw) {
  let s = String(raw ?? "").replace(/[\u0000-\u0008\u000b-\u001f\u007f]/g, "").replace(/\s+/g, " ").trim();
  return Array.from(s).slice(0, CHAT_MAX_LEN).join("");
}

function allowedOrigin(request, env) {
  const list = String(env.ALLOWED_ORIGINS || "*").split(",").map((s) => s.trim()).filter(Boolean);
  const origin = request.headers.get("Origin");
  if (list.includes("*")) return origin || "*";
  if (!origin) return null; // 브라우저가 아닌 요청은 허용 목록이 있을 때 거절
  if (list.includes(origin)) return origin;
  // 와일드카드 서브도메인: https://*.my-game.pages.dev (Pages 미리보기 배포 대응)
  for (const pat of list) {
    if (!pat.includes("*.")) continue;
    const [scheme, host] = pat.split("://");
    const suffix = host.replace(/^\*\./, ".");
    try {
      const u = new URL(origin);
      if (u.protocol === scheme + ":" && u.hostname.endsWith(suffix)) return origin;
    } catch {}
  }
  return null;
}

function corsHeaders(origin) {
  return {
    "Access-Control-Allow-Origin": origin || "*",
    "Access-Control-Allow-Methods": "GET,POST,OPTIONS",
    "Access-Control-Allow-Headers": "content-type",
    "Access-Control-Max-Age": "86400",
    Vary: "Origin",
  };
}

